import{_ as t,c as r,o as s,ah as n}from"./chunks/framework.RCw5T9E9.js";const h=JSON.parse('{"title":"Чёрный список","description":"","frontmatter":{"title":"Чёрный список"},"headers":[],"relativePath":"ru/props/blacklist.md","filePath":"ru/props/blacklist.md"}'),e={name:"ru/props/blacklist.md"};function l(a,o,g,d,i,p){return s(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="черныи-список-компонентов-props" tabindex="-1">Чёрный список компонентов (Props) <a class="header-anchor" href="#черныи-список-компонентов-props" aria-label="Permalink to &quot;Чёрный список компонентов (Props)&quot;">​</a></h1><p><strong>Чёрный список</strong> во вкладке <strong>Props</strong> — это набор <strong>имён Vue-компонентов</strong>, которые исключаются из дерева инспектора и не отображаются в таблице. Фильтрация применяется <strong>до построения списка props</strong>, поэтому скрытые компоненты не участвуют в обычном обходе дерева.</p><p>Общее описание вкладки Props: <a href="/qa-tools/docs/ru/props/general.html">Основные возможности</a>.</p><p>Не путайте этот список с <strong>чёрным списком сайтов</strong> для <strong>автозапуска</strong> оверлея (настройки <strong>General / Auto Run</strong>): здесь фильтрация относится только к <strong>именам компонентов</strong>.</p><hr><h2 id="где-добавить-и-убрать" tabindex="-1">Где добавить и убрать <a class="header-anchor" href="#где-добавить-и-убрать" aria-label="Permalink to &quot;Где добавить и убрать&quot;">​</a></h2><p>Добавить компонент в чёрный список можно двумя способами.</p><ul><li><strong>Ignore by name</strong> в меню строки добавляет текущее имя в <strong>Blocked</strong>. Пустое имя пропускается. Имя, которое уже есть в <strong>Blocked</strong> или <strong>Allowed</strong>, повторно не добавляется.</li><li><strong>Options → Props → Component Blacklist</strong> — список и карточка деталей описаны ниже.</li></ul><hr><h2 id="blocked-и-allowed" tabindex="-1">Blocked и Allowed <a class="header-anchor" href="#blocked-и-allowed" aria-label="Permalink to &quot;Blocked и Allowed&quot;">​</a></h2><p>Список правил делится на два состояния.</p><ul><li><strong>Blocked</strong> — совпавшее имя скрывается.</li><li><strong>Allowed</strong> — исключение. Имя, которое совпало с любым правилом <strong>Allowed</strong>, остаётся в списке, даже если его накрывает правило <strong>Blocked</strong>.</li></ul><p>Правила <strong>Allowed</strong> ничего не делают, пока нет ни одного <strong>Blocked</strong>. Удаление строки полностью убирает правило.</p><h3 id="component-blacklist-в-options" tabindex="-1">Component Blacklist в Options <a class="header-anchor" href="#component-blacklist-в-options" aria-label="Permalink to &quot;Component Blacklist в Options&quot;">​</a></h3><p>Блок стоит после <strong>Inspect Mode</strong>. Подсказка поля: <strong>Component name (supports wildcards: <em>Comp</em>)</strong>. <strong>Add</strong> или <strong>Enter</strong> обрезает пробелы и добавляет строку в <strong>Blocked</strong>. Пустое значение: <strong>Name cannot be empty</strong>. Та же сохранённая строка уже в <strong>Blocked</strong> или <strong>Allowed</strong>: <strong>This name is already in the blacklist</strong>. Проверка дубликата учитывает регистр, поэтому <code>Foo</code> и <code>foo</code> — два правила; само сопоставление имён регистр игнорирует.</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Что показывает</th></tr></thead><tbody><tr><td><strong>Component Name</strong></td><td>Сохранённый шаблон.</td></tr><tr><td><strong>Status</strong></td><td><strong>Blocked</strong> или <strong>Allowed</strong>. Строки <strong>Allowed</strong> приглушены.</td></tr></tbody></table><p>Сначала идут все <strong>Blocked</strong>, затем <strong>Allowed</strong>, в порядке добавления. Меню строки (правый клик или <strong>⋮</strong>): <strong>Allow</strong> или <strong>Block</strong>, и <strong>Delete</strong>. Пустая таблица: <em>No components in blacklist</em>.</p><p>Клик открывает <strong>Blacklist Details</strong>: <strong>Component Name</strong> и <strong>Status</strong> (<strong>Blocked</strong> или <strong>Allowed</strong>). Кнопки <strong>Edit</strong> нет. <strong>Назад</strong> или <strong>Escape</strong> закрывают карточку. Если ничего не выбрано, панель пишет <em>Select an item to see details</em>. Если правило удалили при открытой карточке, она пишет <em>Item no longer exists</em>. Ниже <strong>1000</strong> px карточка закрывает список настроек, пока её не закроют.</p><p>Карточка не выбирает этот компонент на вкладке Props.</p><hr><h2 id="как-сопоставляется-имя" tabindex="-1">Как сопоставляется имя <a class="header-anchor" href="#как-сопоставляется-имя" aria-label="Permalink to &quot;Как сопоставляется имя&quot;">​</a></h2><p>Сравнение выполняется по <strong>имени компонента</strong>, которое отображается в инспекторе.</p><ul><li>Если правило <strong>не содержит</strong> символов <strong><code>*</code></strong> или <strong><code>%</code></strong>, используется <strong>точное совпадение</strong> без учёта регистра.</li><li>Символы <strong><code>*</code></strong> и <strong><code>%</code></strong> работают как шаблон подстановки произвольного фрагмента имени.</li></ul><p>Например:</p><ul><li><code>MyButton</code> — скрывает только компонент с точным именем <strong>MyButton</strong>;</li><li><code>Base*</code> — скрывает все компоненты, имя которых начинается с <strong>Base</strong>;</li><li><code>*Modal*</code> — скрывает все имена, содержащие <strong>Modal</strong>.</li></ul><p>Для безымянных компонентов может использоваться внутреннее обозначение вроде <strong>Anonymous</strong>, если оно присутствует в дереве.</p><hr><h2 id="исключения-и-пересечения" tabindex="-1">Исключения и пересечения <a class="header-anchor" href="#исключения-и-пересечения" aria-label="Permalink to &quot;Исключения и пересечения&quot;">​</a></h2><p>Любое совпадение <strong>Allowed</strong> побеждает: имя остаётся видимым. Иначе любое совпадение <strong>Blocked</strong> его скрывает.</p><p>Широкое правило <strong>Blocked</strong> вместе с более узким <strong>Allowed</strong> оставляет исключение на экране. Перевод широкого правила в <strong>Allowed</strong> делает этот шаблон исключением для каждого подходящего имени.</p><hr><h2 id="когда-применяется" tabindex="-1">Когда применяется <a class="header-anchor" href="#когда-применяется" aria-label="Permalink to &quot;Когда применяется&quot;">​</a></h2><p>Актуальный список правил используется при каждом обновлении дерева:</p><ul><li>при ручном <strong>Refresh</strong>;</li><li>при автоматическом обновлении списка;</li><li>при повторном открытии вкладки.</li></ul><p>Если в таблице Props уже есть строки, правка в <strong>Options</strong> её обновляет. Пустой список подхватывает правила при следующем перестроении.</p><p>Пока правило <strong>Blocked</strong> скрывает имя, этот компонент нельзя выбрать в таблице и карточке.</p><hr><h2 id="практические-советы" tabindex="-1">Практические советы <a class="header-anchor" href="#практические-советы" aria-label="Permalink to &quot;Практические советы&quot;">​</a></h2><ul><li>Начинать удобнее с <strong>точного имени</strong> через контекстное меню строки.</li><li><strong>Широкие маски</strong> подходят для повторяющихся служебных компонентов, но требуют аккуратности.</li><li>Чёрный список влияет только на <strong>отображение в инспекторе</strong> и не изменяет работу Vue-приложения.</li></ul><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/ru/props/general.html">Основные возможности Props</a></li><li><a href="/qa-tools/docs/ru/props/inspect.html">Инспектор (выбор на странице)</a></li><li><a href="/qa-tools/docs/ru/options/customize.html">Персонализация / настройки</a></li></ul>',42)])])}const u=t(e,[["render",l]]);export{h as __pageData,u as default};
